  app.post("/api/tefca/partners/onboard/:token/submit", requireAuth, async (req: Request, res: Response) => {
    try {
      const { token } = req.params as any;
      const { fhirEndpoint, authMethod, fhirVersion, uscdiVersions, capabilities } = req.body as any;

      let onboarding: any = null;
      for (const entry of onboardingRequests.values()) {
        if (entry.onboardingToken === token) {
          onboarding = entry;
          break;
        }
      }

      if (!onboarding || (onboarding.status !== "invited" && onboarding.status !== "submitted")) {
        return res.status(404).json({ error: "Onboarding request not found or not in a valid state" });
      }

      if (!fhirEndpoint || !authMethod) {
        return res.status(400).json({ error: "fhirEndpoint and authMethod are required" });
      }

      onboarding.fhirEndpoint = fhirEndpoint;
      onboarding.authMethod = authMethod;
      onboarding.status = "submitted";

      const partnerId = onboarding.partnerName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
      let partner;
      try {
        partner = tefcaFrameworkService.registerPartner({
          id: partnerId,
          name: onboarding.partnerName,
          endpointUrl: fhirEndpoint,
          supportedUscdiVersions: uscdiVersions || ["v3"],
          type: onboarding.partnerType,
          authMethod,
          fhirVersion: fhirVersion || "R4",
          capabilities: capabilities || ["patient-match", "document-query"],
        });
      } catch (regError: any) {
        if (regError.message?.includes("already exists")) {
          partner = tefcaFrameworkService.getNetwork(partnerId);
        } else {
          throw regError;
        }
      }

      const testResult = await tefcaFrameworkService.testPartnerConnection(partnerId);
      onboarding.testResult = testResult;

      if (testResult.success) {
        onboarding.status = "completed";
        onboarding.completedAt = new Date().toISOString();
      } else {
        onboarding.status = "submitted";
      }

      auditLog(req, "tefca_partner_onboard_submit", "tefca", onboarding.id, { partnerId, testSuccess: testResult.success });
      res.json({ onboarding, partner, testResult, message: testResult.success ? "Onboarding completed successfully" : "Partner registered but connection test failed" });
    } catch (error) {
      logger.error("TEFCA partner onboard submit error", { category: "api", error });
      res.status(500).json({ error: "Failed to submit onboarding details" });
    }
  });


