  // ==================== WEARABLE DATA IMPORT ====================


  app.post("/api/wearables/import/:platform", requireAuth, async (req, res) => {
    try {
      const userId = getUserId(req);
      const platform = (req.params as any).platform;
      const rawData = req.body as any;
      
      const validPlatforms = ["fitbit", "garmin", "samsung_health", "apple_health", "google_fit", "oura", "whoop", "withings", "dexcom", "suunto", "polar", "amazfit", "coros"];
      if (!validPlatforms.includes(platform)) {
        return res.status(400).json({ error: `Unsupported platform: ${platform}` });
      }

      const result = wearableDeviceService.importPlatformData(userId, platform as any, rawData);

      if (result.lineageRecord) {
        try {
          const lineageId = `wearable_import_${platform}_${Date.now()}`;
          dataLineageService.createLineageRecord(
            lineageId, userId, "wearable_data", 
            `${result.lineageRecord.sourcePlatform} Import`,
            `wearable_${platform}`,
            {
              sourceType: result.lineageRecord.sourceType,
              sourcePlatform: result.lineageRecord.sourcePlatform,
              importedAt: result.lineageRecord.importedAt,
              recordCount: result.lineageRecord.recordCount,
              categories: result.lineageRecord.categories
            }
          );

          for (const transformation of result.lineageRecord.transformations) {
            dataLineageService.addTransformation(
              lineageId,
              transformation,
              `${transformation} applied to ${platform} data`,
              "wearable_import_service",
            );
          }
        } catch (lineageError) {
          console.error("Lineage recording error (non-fatal):", lineageError);
        }
      }

      auditLog(req, "wearable_import", "wearable", userId, {
        platform,
        dataPointsImported: result.dataPoints.length,
        anomaliesDetected: result.anomalies.length,
        errors: result.errors.length
      });

      res.json({
        success: true,
        platform,
        dataPointsImported: result.dataPoints.length,
        healthGraphEntities: result.healthGraphEntities.length,
        anomaliesDetected: result.anomalies.length,
        categories: [...new Set(result.dataPoints.map(dp => dp.category))],
        lineage: result.lineageRecord,
        errors: result.errors
      });
    } catch (error) {
      console.error("Wearable import error:", error);
      res.status(500).json({ error: "Failed to import wearable data" });
    }
  });

